BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP106-2-25','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-07-29。考試時適用之性別工作平等法第23條（2016-05-18 修正公布）第1項規定僱用受僱者一百人以上之雇主，應提供哺（集）乳室、托兒設施或適當之托兒措施，官方答案A。該法於 2023-08-16 修正名稱為性別平等工作法，第23條其後未再修正，現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-27 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030014'),('SP106-2-35','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-07-29。考試時適用之老人福利法第43條（2014-06-04 修正公布）第3項規定直轄市、縣（市）主管機關接獲通報後，應立即處理，必要時得進行訪視調查，官方答案A。其後 2015-12-09、2020-05-27、2025-08-01 修正均未涉及第43條，現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-27 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050037'),('SP107-1-40','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。考試時適用之兒童及少年福利與權益保障法第75條（2011-11-30 修正公布全文）第1項規定兒童及少年福利機構分為托嬰中心、早期療育機構、安置及教養機構、心理輔導或家庭諮詢機構及其他兒童及少年福利機構，幼兒園不在其中，官方答案B。第75條其後未再修正，現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-27 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050001'),('SP111-2-37','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2022-07-30。考試時適用之精神衛生法第4條（2020-01-15 修正公布）第2項規定中央主管機關應每四年公布國家心理衛生報告，官方答案C。該法於 2022-12-14 修正公布全文，依第91條自公布後二年施行；現行第4條第1項所列掌理事項雖有調整，第2項仍規定中央主管機關應每四年公布國家心理衛生報告，本題考點未變。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-27 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0020030'),('SP113-1-30','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2024-02-04。本題考試時適用 2023-12-06 修正公布、依第66條自公布日施行之家庭暴力防治法，即現行條文：第2條規定家庭暴力包括經濟上之騷擾、控制、脅迫，並定義目睹家庭暴力及含親職教育輔導之加害人處遇計畫；第15條規定通常保護令之有效期間為二年以下，每次延長為二年以下，選項D所稱有效期限延長為5年錯誤，官方答案D。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-27 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP113-1-31','not_applicable',NULL,NULL),('SP113-1-32','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2024-02-04。考試時社會救助法第8條（2010-12-29 修正公布）規定依本法或其他法令每人每月所領取政府核發之救助總金額，不得超過當年政府公告之基本工資；最低工資法雖於 2024-01-01 施行，惟依其第15條，中央主管機關首次公告實施最低工資前，原依勞動基準法公告之基本工資繼續有效，官方答案D。現行條文：社會救助法第8條文字仍為基本工資，但最低工資法第18條規定本法施行後其他法規關於基本工資之規定適用最低工資之規定，首次公告實施最低工資後，救助總金額上限應以當年公告之最低工資為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-27 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0030028'),('SP113-1-33','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2024-02-04。本題考試時適用 2023-06-09 增訂公布、依第51條自公布日施行之社會工作師法第17條之3，即現行條文：移付懲戒事件由社會工作師懲戒委員會處理；應限被付懲戒之社會工作師於通知送達之翌日起二十日內提出答辯或到會陳述；不服決議者得於決議書送達之翌日起二十日內請求覆審；懲戒委員會與覆審委員會委員中法學專家學者及社會人士之比例不得少於三分之一，選項D所稱二分之一錯誤，官方答案D。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-27 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050125'),('SP113-1-38','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2024-02-04。考試時適用之國民年金法第40條（2020-06-03 修正公布）即現行條文：孫子女應受被保險人扶養，並為未成年、無謀生能力或二十五歲以下在學且每月工作收入未超過其領取遺屬年金給付時之基本工資者，始得請領遺屬年金給付；民法第12條（2021-01-13 修正公布、2023-01-01 施行）規定滿十八歲為成年，19歲已畢業工作之孫子女不符條件，官方答案A。另依最低工資法第18條，第40條所定基本工資現適用最低工資之規定，不影響本題答案。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-27 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050152'),('SP113-1-40','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2024-02-04。長期照顧服務機構法人條例第11條規定長照機構法人之董事會每半年至少開會一次，由董事長召集，官方答案B。該條例 2018-01-31 制定公布、自公布日施行後未曾修正，考試時條文即現行條文。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-27 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070051'),('SW-106-1-40','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。考試時適用之家庭暴力防治法第3條（2007-03-28 修正公布全文）規定家庭成員包括配偶或前配偶、現有或曾有同居關係、家長家屬或家屬間關係者、現為或曾為直系血親或直系姻親、現為或曾為四親等以內之旁系血親或旁系姻親及其未成年子女；堂外甥為五親等旁系血親，不屬家庭成員，官方答案C。現行第3條（2023-12-06 修正公布、依第66條自公布日施行）改以第5款至第7款規定四親等以內血親之配偶、配偶之四親等以內血親及其配偶，女婿（血親之配偶）、前夫（前配偶）、同住之子女仍屬家庭成員，堂外甥仍不屬之。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-27 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>11 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL AND q.analysis_status='ready')<>11 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at=CASE WHEN b.status='not_applicable' THEN NULL ELSE '2026-11-27T06:00:00+00:00'::timestamptz END, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id COLLATE "C")) FROM public.questions q JOIN swsi_batch b USING(id)) IS DISTINCT FROM '639e7907c7649ba5d468769ec188dcc0' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status=b.status AND q.legal_note IS NOT DISTINCT FROM b.note AND q.legal_source_url IS NOT DISTINCT FROM b.url AND q.legal_checked_at IS NOT DISTINCT FROM (CASE WHEN b.status='not_applicable' THEN NULL ELSE '2026-11-27T06:00:00+00:00'::timestamptz END))<>11 THEN RAISE EXCEPTION 'postimage count'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_9, count(*) FILTER (WHERE q.legal_status='changed') changed_1, count(*) FILTER (WHERE q.legal_status='not_applicable') na_1, count(*) total_11 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
